using System.Security.Cryptography;using System.Text;using System.Text.Json;using System.Text.Json.Nodes;using System.Diagnostics;
namespace CommanderOwnerConsent;
internal static class StoreQA
{
    private static readonly List<object> results=[];private static string root="";private static int next;
    private static void Check(string name,Action f){try{f();results.Add(new{name,status="PASS"});}catch(Exception e){results.Add(new{name,status="FAIL",error=e.GetType().Name,code=e.Message});}}
    private static void Denies(Action f,string code){try{f();}catch(ConsentFault e){if(e.Message==code)return;throw;}throw new Exception("EXPECTED_DENIAL:"+code);}
    private static byte[] Bytes(JsonNode n)=>Encoding.UTF8.GetBytes(n.ToJsonString(new(){Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping}));
    private static JsonObject Grant()=>new(){["profileId"]="fixture",["rootPolicyId"]="fixture-root",["actions"]=new JsonArray("read_text"),["scopes"]=new JsonArray("commander:read")};
    private static JsonObject Policy(ECDsa k)=>new(){["schema"]="RC_OWNER_CONSENT_POLICY_V1",["issuer"]="https://issuer.invalid/a&b",["resource"]="https://resource.invalid/mcp",["ownerId"]="fixture-owner",["ownerSid"]="S-1-5-21-111-222-333-1001",["enrollmentEpoch"]="epoch:fixture",["helperSha256"]=new string('a',64),["signingPublicKeySpkiSha256"]=Convert.ToHexString(SHA256.HashData(k.ExportSubjectPublicKeyInfo())).ToLowerInvariant(),["clients"]=new JsonArray(new JsonObject{["clientId"]="https://client.invalid/client.json",["redirectUris"]=new JsonArray("https://client.invalid/callback")}),["grantCatalog"]=new JsonArray(new JsonObject{["grantPolicyId"]="read-only",["grant"]=Grant()})};
    private static JsonObject Request(string state="fixture-state-123456789")=>new(){["response_type"]="code",["client_id"]="https://client.invalid/client.json",["redirect_uri"]="https://client.invalid/callback",["resource"]="https://resource.invalid/mcp",["code_challenge_method"]="S256",["code_challenge"]=new string('C',43),["state"]=state,["grant_policy_id"]="read-only"};
    private sealed class Fixture:IDisposable
    {internal readonly string Path;internal readonly ECDsa Key=ECDsa.Create(ECCurve.NamedCurves.nistP256);internal readonly byte[] PolicyBytes;internal ProtectedIssuerState Store;internal Fixture(){Path=System.IO.Path.Combine(root,"f"+(++next));PolicyBytes=Bytes(Policy(Key));Store=ProtectedIssuerState.OpenFixture(Path,PolicyBytes,Key.ExportSubjectPublicKeyInfoPem());File.WriteAllBytes(System.IO.Path.Combine(Path,"fixture-policy.json"),PolicyBytes);File.WriteAllText(System.IO.Path.Combine(Path,"fixture-public.pem"),Key.ExportSubjectPublicKeyInfoPem());}internal void Reopen(){Store.Dispose();Store=ProtectedIssuerState.OpenFixture(Path,PolicyBytes,Key.ExportSubjectPublicKeyInfoPem());}public void Dispose(){Store.Dispose();Key.Dispose();}}
    private static void Receipt(Fixture f,PendingSummary p,string receiptId="DDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDD",ECDsa? key=null,bool changeDigest=false)
    {
        using var policy=ConsentCore.Strict(f.PolicyBytes);var raw=File.ReadAllBytes(System.IO.Path.Combine(f.Path,"pending",p.RequestId+".json"));var pending=ConsentCore.ValidatePending(raw,policy.RootElement,p.RequestId,DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());if(changeDigest)pending=pending with{RequestDigest=new string('Z',43)};
        var statement=ConsentCore.Statement(pending,DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),receiptId);var message=Encoding.UTF8.GetBytes("RC_OWNER_OAUTH_CONSENT_V1\n").Concat(statement).ToArray();var sig=(key??f.Key).SignData(message,HashAlgorithmName.SHA256,DSASignatureFormat.Rfc3279DerSequence);
        using var m=new MemoryStream();using(var w=new Utf8JsonWriter(m)){w.WriteStartObject();w.WritePropertyName("statement");w.WriteRawValue(statement,false);w.WriteString("signature",ConsentCore.B64(sig));w.WriteEndObject();}File.WriteAllBytes(System.IO.Path.Combine(f.Path,"receipts",p.RequestId+".json"),m.ToArray());
    }
    private static void Crash(Fixture f,string stage,bool consume=false)
    {
        var info=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};info.ArgumentList.Add("--crash");info.ArgumentList.Add(f.Path);info.ArgumentList.Add(stage);info.ArgumentList.Add(consume?"consume":"begin");
        using var p=Process.Start(info)??throw new Exception("CHILD_START");ConsentCore.Need(p.WaitForExit(15000)&&p.ExitCode==71,"FIXTURE_CHILD_EXIT");
    }
    private static int Main(string[] args)
    {
        if(args.Length==4&&args[0]=="--crash")
        {var directory=System.IO.Path.GetFullPath(args[1]);ConsentCore.Need(directory.StartsWith(System.IO.Path.GetFullPath(Environment.GetEnvironmentVariable("R78_ISSUER_FIXTURE_ROOT")!)+System.IO.Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase),"FIXTURE_CHILD_ROOT");using var s=ProtectedIssuerState.OpenFixture(directory,File.ReadAllBytes(System.IO.Path.Combine(directory,"fixture-policy.json")),File.ReadAllText(System.IO.Path.Combine(directory,"fixture-public.pem")));s.CrashAt=args[2];if(args[3]=="consume"){var id=System.IO.Path.GetFileNameWithoutExtension(Directory.GetFiles(System.IO.Path.Combine(directory,"pending")).Single());s.ConsumeNativeReceipt(id);}else s.Begin(Bytes(Request()));return 99;}
        root=Environment.GetEnvironmentVariable("R78_ISSUER_FIXTURE_ROOT")??throw new Exception("FIXTURE_ROOT_REQUIRED");Directory.CreateDirectory(root);
        Check("native pending exact policy/digest contract",()=>{using var f=new Fixture();var p=f.Store.Begin(Bytes(Request()));using var policy=ConsentCore.Strict(f.PolicyBytes);var bound=ConsentCore.ValidatePending(File.ReadAllBytes(System.IO.Path.Combine(f.Path,"pending",p.RequestId+".json")),policy.RootElement,p.RequestId,DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());ConsentCore.Need(bound.RequestDigest==p.RequestDigest,"NATIVE_CONTRACT");File.Copy(System.IO.Path.Combine(f.Path,"pending",p.RequestId+".json"),System.IO.Path.Combine(root,"interop-pending.json"));});
        Check("same client state reuses committed pending without reissue",()=>{using var f=new Fixture();var a=f.Store.Begin(Bytes(Request()));var count=File.ReadAllLines(System.IO.Path.Combine(f.Path,"issuer.journal")).Length;f.Reopen();var b=f.Store.Begin(Bytes(Request()));ConsentCore.Need(a.RequestId==b.RequestId&&b.ReusedExisting&&count==File.ReadAllLines(System.IO.Path.Combine(f.Path,"issuer.journal")).Length,"DUPLICATE_REISSUE");});
        Check("same state changed challenge denied",()=>{using var f=new Fixture();f.Store.Begin(Bytes(Request()));var r=Request();r["code_challenge"]=new string('X',43);Denies(()=>f.Store.Begin(Bytes(r)),"CLIENT_STATE_BINDING_CHANGED");});
        Check("resource mismatch denied",()=>{using var f=new Fixture();var r=Request();r["resource"]="https://other.invalid/mcp";Denies(()=>f.Store.Begin(Bytes(r)),"RESOURCE_BINDING");});
        Check("callback mismatch denied",()=>{using var f=new Fixture();var r=Request();r["redirect_uri"]="https://other.invalid/callback";Denies(()=>f.Store.Begin(Bytes(r)),"CLIENT_REDIRECT_BINDING");});
        Check("unknown client denied",()=>{using var f=new Fixture();var r=Request();r["client_id"]="https://other.invalid/client.json";Denies(()=>f.Store.Begin(Bytes(r)),"CLIENT_REDIRECT_BINDING");});
        Check("unknown grant denied",()=>{using var f=new Fixture();var r=Request();r["grant_policy_id"]="all";Denies(()=>f.Store.Begin(Bytes(r)),"GRANT_POLICY_BINDING");});
        Check("plain PKCE denied",()=>{using var f=new Fixture();var r=Request();r["code_challenge_method"]="plain";Denies(()=>f.Store.Begin(Bytes(r)),"AUTHORIZATION_CODE_S256_REQUIRED");});
        Check("public approved boolean denied",()=>{using var f=new Fixture();var r=Request();r["approved"]=true;Denies(()=>f.Store.Begin(Bytes(r)),"JSON_SCHEMA");});
        Check("duplicate JSON denied",()=>{using var f=new Fixture();Denies(()=>f.Store.Begin(Encoding.UTF8.GetBytes("{\"state\":1,\"state\":2}")),"DUPLICATE_JSON_PROPERTY");});
        Check("real fixture receipt consumes once across reopen no token",()=>{using var f=new Fixture();var p=f.Store.Begin(Bytes(Request()));Receipt(f,p);var result=f.Store.ConsumeNativeReceipt(p.RequestId);ConsentCore.Need(!result.TokenIssued&&result.Status=="CONSENT_CONSUMED_TOKEN_NOT_ISSUED","TOKEN_NOT_ISSUED");f.Reopen();Denies(()=>f.Store.ConsumeNativeReceipt(p.RequestId),"REQUEST_CONSUMED_OR_RECONCILIATION_REQUIRED");Denies(()=>f.Store.Begin(Bytes(Request())),"REQUEST_CONSUMED_OR_RECONCILIATION_REQUIRED");});
        Check("wrong signature denied before consume intent",()=>{using var f=new Fixture();var p=f.Store.Begin(Bytes(Request()));using var wrong=ECDsa.Create(ECCurve.NamedCurves.nistP256);Receipt(f,p,key:wrong);Denies(()=>f.Store.ConsumeNativeReceipt(p.RequestId),"NATIVE_RECEIPT_SIGNATURE");ConsentCore.Need(f.Store.ReadStatus(p.RequestId)=="PENDING_COMMITTED","SIGNATURE_EFFECT");});
        Check("signed foreign digest denied",()=>{using var f=new Fixture();var p=f.Store.Begin(Bytes(Request()));Receipt(f,p,changeDigest:true);Denies(()=>f.Store.ConsumeNativeReceipt(p.RequestId),"NATIVE_RECEIPT_BINDING");});
        Check("receipt identity cannot authorize second request",()=>{using var f=new Fixture();var a=f.Store.Begin(Bytes(Request()));Receipt(f,a);f.Store.ConsumeNativeReceipt(a.RequestId);var b=f.Store.Begin(Bytes(Request("different-fixture-state-123")));Receipt(f,b);Denies(()=>f.Store.ConsumeNativeReceipt(b.RequestId),"RECEIPT_REPLAY");});
        Check("revocation terminal no pending replay",()=>{using var f=new Fixture();var p=f.Store.Begin(Bytes(Request()));Receipt(f,p);f.Store.Revoke(p.RequestId);f.Reopen();ConsentCore.Need(f.Store.ReadStatus(p.RequestId)=="REVOKED","REVOCATION");Denies(()=>f.Store.ConsumeNativeReceipt(p.RequestId),"REQUEST_CONSUMED_OR_RECONCILIATION_REQUIRED");Denies(()=>f.Store.Begin(Bytes(Request())),"REQUEST_CONSUMED_OR_RECONCILIATION_REQUIRED");Denies(()=>f.Store.Revoke(p.RequestId),"ALREADY_REVOKED");});
        Check("revocation after consumption recorded without job effects",()=>{using var f=new Fixture();var p=f.Store.Begin(Bytes(Request()));Receipt(f,p);f.Store.ConsumeNativeReceipt(p.RequestId);f.Store.Revoke(p.RequestId);f.Reopen();ConsentCore.Need(f.Store.ReadStatus(p.RequestId)=="REVOKED","REVOCATION");});
        Check("partial journal tail not silently repaired",()=>{using var f=new Fixture();f.Store.Begin(Bytes(Request()));var path=System.IO.Path.Combine(f.Path,"issuer.journal");File.AppendAllText(path,"{");var before=File.ReadAllBytes(path);f.Reopen();Denies(()=>f.Store.Begin(Bytes(Request("new-state-123456789"))),"JOURNAL_PARTIAL_TAIL_REVIEW_REQUIRED");ConsentCore.Need(before.SequenceEqual(File.ReadAllBytes(path)),"JOURNAL_REPAIRED");});
        Check("journal hash corruption fails closed",()=>{using var f=new Fixture();f.Store.Begin(Bytes(Request()));var path=System.IO.Path.Combine(f.Path,"issuer.journal");var text=File.ReadAllText(path).Replace("BEGIN_PREPARED","BEGIN_CORRUPTED",StringComparison.Ordinal);File.WriteAllText(path,text);f.Reopen();Denies(()=>f.Store.Begin(Bytes(Request("new-state-123456789"))),"JOURNAL_INTEGRITY_REVIEW_REQUIRED");});
        Check("exclusive writer conflict causes zero new records",()=>{using var f=new Fixture();f.Store.Begin(Bytes(Request()));var path=System.IO.Path.Combine(f.Path,"issuer.journal");var before=File.ReadAllBytes(path);using var held=new FileStream(System.IO.Path.Combine(f.Path,"writer.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None);try{f.Store.Begin(Bytes(Request("new-state-123456789")));throw new Exception("LOCK_BYPASSED");}catch(IOException){}ConsentCore.Need(before.SequenceEqual(File.ReadAllBytes(path)),"CONCURRENT_MUTATION");});
        Check("actual child exit after prepared prevents new issuance",()=>{using var f=new Fixture();Crash(f,"AFTER_PREPARED");f.Reopen();Denies(()=>f.Store.Begin(Bytes(Request())),"REQUEST_CONSUMED_OR_RECONCILIATION_REQUIRED");ConsentCore.Need(Directory.GetFiles(System.IO.Path.Combine(f.Path,"pending")).Length==0,"CRASH_REPLAY");});
        Check("actual child exit after pending file not auto committed",()=>{using var f=new Fixture();Crash(f,"AFTER_PENDING_FILE");f.Reopen();Denies(()=>f.Store.Begin(Bytes(Request())),"REQUEST_CONSUMED_OR_RECONCILIATION_REQUIRED");ConsentCore.Need(Directory.GetFiles(System.IO.Path.Combine(f.Path,"pending")).Length==1,"CRASH_REPLAY");});
        Check("actual child exit during consume never consumes again",()=>{using var f=new Fixture();var p=f.Store.Begin(Bytes(Request()));Receipt(f,p);Crash(f,"AFTER_CONSUME_PREPARED",true);f.Reopen();ConsentCore.Need(f.Store.ReadStatus(p.RequestId)=="CONSUME_PREPARED","CONSUME_INTENT");Denies(()=>f.Store.ConsumeNativeReceipt(p.RequestId),"REQUEST_CONSUMED_OR_RECONCILIATION_REQUIRED");});
        Check("bounded admission preserves terminal capacity",()=>{using var f=new Fixture();for(int i=0;i<128;i++)f.Store.Begin(Bytes(Request("bounded-fixture-state-"+i)));Denies(()=>f.Store.Begin(Bytes(Request("bounded-fixture-state-over-capacity"))),"ISSUER_TRANSACTION_CAPACITY");});
        Check("unknown request path cannot select arbitrary receipt",()=>{using var f=new Fixture();Denies(()=>f.Store.ConsumeNativeReceipt("../../other"),"UNKNOWN_REQUEST");});
        Check("public key pin is cryptographically enforced",()=>{using var f=new Fixture();using var wrong=ECDsa.Create(ECCurve.NamedCurves.nistP256);Denies(()=>{using var s=ProtectedIssuerState.OpenFixture(System.IO.Path.Combine(root,"wrong-pin"),f.PolicyBytes,wrong.ExportSubjectPublicKeyInfoPem());},"ISSUER_CONSENT_PUBLIC_KEY_PIN");});
        Check("epoch drift rejects existing pending without reissue",()=>{using var f=new Fixture();f.Store.Begin(Bytes(Request()));var p=JsonNode.Parse(f.PolicyBytes)!;p["enrollmentEpoch"]="epoch:new";using var s=ProtectedIssuerState.OpenFixture(f.Path,Bytes(p),f.Key.ExportSubjectPublicKeyInfoPem());Denies(()=>s.Begin(Bytes(Request())),"ISSUER_ENROLLMENT_POLICY_CHANGED");});
        Check("fixture factory and crash injection absent in production assembly",()=>{var assembly=System.Reflection.Assembly.LoadFile(System.IO.Path.GetFullPath(Environment.GetEnvironmentVariable("R78_PRODUCTION_STORE_DLL")!));var type=assembly.GetType("CommanderOwnerConsent.ProtectedIssuerState")!;var flags=System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.Instance;ConsentCore.Need(type.GetMethod("OpenFixture",flags)==null&&type.GetField("CrashAt",flags)==null,"FIXTURE_PATH_IN_PRODUCTION");});
        Check("owner denial is terminal without authorization",()=>{using var f=new Fixture();var p=f.Store.Begin(Bytes(Request()));File.WriteAllText(System.IO.Path.Combine(f.Path,"receipts",p.RequestId+".json"),JsonSerializer.Serialize(new{status="OWNER_DENIED_OR_TIMEOUT",requestId=p.RequestId,requestDigest=p.RequestDigest,automaticRetryAllowed=false}));var result=f.Store.ConsumeNativeReceipt(p.RequestId);ConsentCore.Need(result.Status=="OWNER_DENIED_TOKEN_NOT_ISSUED"&&!result.TokenIssued,"DENIAL");f.Reopen();ConsentCore.Need(f.Store.ReadStatus(p.RequestId)=="OWNER_DENIED","DENIAL_NOT_DURABLE");Denies(()=>f.Store.Begin(Bytes(Request())),"REQUEST_CONSUMED_OR_RECONCILIATION_REQUIRED");});
        Check("missing journal never becomes fresh issuance",()=>{using var f=new Fixture();f.Store.Begin(Bytes(Request()));File.Delete(System.IO.Path.Combine(f.Path,"issuer.journal"));f.Reopen();Denies(()=>f.Store.Begin(Bytes(Request())),"JOURNAL_MISSING_REVIEW_REQUIRED");ConsentCore.Need(!File.Exists(System.IO.Path.Combine(f.Path,"issuer.journal")),"JOURNAL_RECREATED");});
        Check("missing head requires review",()=>{using var f=new Fixture();f.Store.Begin(Bytes(Request()));File.Delete(System.IO.Path.Combine(f.Path,"issuer.head.json"));f.Reopen();Denies(()=>f.Store.Begin(Bytes(Request())),"JOURNAL_ANCHOR_MISSING_REVIEW_REQUIRED");});
        Check("missing initialization marker requires review",()=>{using var f=new Fixture();f.Store.Begin(Bytes(Request()));File.Delete(System.IO.Path.Combine(f.Path,"issuer.initialized"));f.Reopen();Denies(()=>f.Store.Begin(Bytes(Request())),"JOURNAL_ANCHOR_MISSING_REVIEW_REQUIRED");});
        Check("complete journal prefix loss detected by independent head file",()=>{using var f=new Fixture();f.Store.Begin(Bytes(Request()));var path=System.IO.Path.Combine(f.Path,"issuer.journal");var first=File.ReadLines(path).First();File.WriteAllText(path,first+"\n");f.Reopen();Denies(()=>f.Store.Begin(Bytes(Request())),"JOURNAL_HEAD_MISMATCH_REVIEW_REQUIRED");});
        Check("actual child exit between journal flush and head blocks recovery",()=>{using var f=new Fixture();Crash(f,"AFTER_JOURNAL_APPEND_BEFORE_HEAD");f.Reopen();Denies(()=>f.Store.Begin(Bytes(Request())),"JOURNAL_HEAD_MISMATCH_REVIEW_REQUIRED");});
        var fail=results.Count(x=>JsonSerializer.Serialize(x).Contains("\"FAIL\"",StringComparison.Ordinal));Console.WriteLine(JsonSerializer.Serialize(new{schema="R78_PROTECTED_ISSUER_FIXTURE_QA_V1",pass=results.Count-fail,fail,cases=results,fixtureOnly=true,ownerEnrollment=false,accessTokensIssued=0,realJobEffects=0,childCrashesSimulatedByIntentionalExit=4}));return fail==0?0:1;
    }
}
